SELECT g.grade_id, g.student_id, g.subject_name, g.semester, g.score, g.grade_point, g.credit, g.reg_date, s.student_num, s.student_name, s.dept_name FROM TB_GRADE g INNER JOIN TB_STUDENT s ON g.student_id = s.student_id WHERE s.del_yn = 'N'
AND g.student_id = #{studentId}
AND (s.student_name LIKE CONCAT('%', #{searchKeyword}, '%') OR g.subject_name LIKE CONCAT('%', #{searchKeyword}, '%'))
AND g.semester = #{searchSemester}
ORDER BY g.semester DESC, s.student_num ASC, g.subject_name ASC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM TB_GRADE g INNER JOIN TB_STUDENT s ON g.student_id = s.student_id WHERE s.del_yn = 'N'
AND g.student_id = #{studentId}
AND (s.student_name LIKE CONCAT('%', #{searchKeyword}, '%') OR g.subject_name LIKE CONCAT('%', #{searchKeyword}, '%'))
AND g.semester = #{searchSemester}

SELECT COUNT(*)
FROM TB_GRADE
WHERE student_id   = #{studentId}
  AND subject_name = #{subjectName}
  AND semester     = #{semester}

    AND grade_id != #{gradeId}
